const fs=require('fs'),validator=require('gltf-validator');
(async()=>{const reports={};for(const name of ['ANT-ONIO','CLAUDIO','AURA-ORBE']){const report=await validator.validateBytes(new Uint8Array(fs.readFileSync('assets/'+name+'.glb')),{uri:name+'.glb',maxIssues:100});reports[name]=report;console.log(name,JSON.stringify({errors:report.issues.numErrors,warnings:report.issues.numWarnings,infos:report.issues.numInfos}));}fs.writeFileSync('qa/gltf-validation.json',JSON.stringify(reports,null,2));if(Object.values(reports).some(r=>r.issues.numErrors||r.issues.numWarnings))process.exitCode=1;})();
